import { isAxiosError } from 'axios';
import { useCallback, useEffect, useState } from 'react';
import api from '../api';
import { apiErrorMessage } from '../utils/apiError';

// Dados da conta do usuário logado e as duas ações da página "Minha conta"
// (SPEC/2026-11-22-auth-perfil-senha.md).

export type AccountUser = {
  id: string;
  email: string;
  full_name: string;
  phone: string | null;
  avatar_url: string | null;
  role: 'admin' | 'barber' | 'client';
  email_verified: boolean;
};

export type ProfileChanges = Partial<Pick<AccountUser, 'full_name' | 'phone' | 'avatar_url'>>;

export type AccountStatus = 'loading' | 'ready' | 'unauthenticated' | 'error';

export function useAccount() {
  const [user, setUser] = useState<AccountUser | null>(null);
  const [status, setStatus] = useState<AccountStatus>('loading');
  const [loadError, setLoadError] = useState('');

  useEffect(() => {
    let active = true;
    api
      .get<AccountUser>('/auth/me')
      .then((response) => {
        if (!active) return;
        setUser(response.data);
        setStatus('ready');
      })
      .catch((error) => {
        if (!active) return;
        // 401 depois do refresh falhar, ou 403 sem token: *** entrar de novo.
        const code = isAxiosError(error) ? error.response?.status : undefined;
        if (code === 401 || code === 403) {
          setStatus('unauthenticated');
        } else {
          setLoadError(apiErrorMessage(error, 'Não foi possível carregar seus dados.'));
          setStatus('error');
        }
      });
    return () => {
      active = false;
    };
  }, []);

  /** Envia só os campos alterados e passa a mostrar o usuário como o backend devolveu. */
  const saveProfile = useCallback(async (changes: ProfileChanges) => {
    const response = await api.put<AccountUser>('/auth/me', changes);
    setUser(response.data);
    return response.data;
  }, []);

  /** Troca a senha e devolve a mensagem de confirmação do backend. */
  const changePassword = *** (currentPassword: ***, newPassword: ***) => {
    const response = await api.put<{ message: string }>('/auth/me/password', {
      current_password: ***,
      new_password: ***,
    });
    return response.data.message;
  }, []);

  return { user, status, loadError, saveProfile, changePassword };
}
import { isAxiosError } from 'axios';

type ValidationIssue = { msg?: string };

/**
 * Mensagem em português para mostrar ao usuário a partir de um erro da API.
 * O 422 do FastAPI traz uma lista de problemas ({ msg }), com o prefixo "Value error, "
 * nas validações escritas no backend; os outros erros trazem `detail` como texto.
 */
export function apiErrorMessage(error: unknown, fallback = 'Não foi possível concluir. Tente de novo.'): string {
  if (!isAxiosError(error)) return fallback;
  if (!error.response) return 'Sem conexão com o servidor. Verifique a internet e tente de novo.';
  const detail = (error.response.data as { detail?: unknown } | undefined)?.detail;
  if (typeof detail === 'string' && detail) return detail;
  if (Array.isArray(detail)) {
    const messages = detail
      .map((issue: ValidationIssue) => (issue?.msg ?? '').replace(/^Value error, /, ''))
      .filter(Boolean);
    if (messages.length) return messages.join(' | ');
  }
  return fallback;
}
